//! The post pages end to end through the router, without a network: an
//! in-memory repository with the same optimistic locking as SQL, the real
//! CSRF, flash and method-override layers, and an access policy that lets
//! every request in (the generated [`DenyAll`] default is tested last).
//! Generated by `forge generate scaffold`.

use std::error::Error;
use std::sync::{Arc, Mutex, MutexGuard};

use app::adapters::http::access::{AccessDenied, DenyAll, GlobalAccess};
use app::application::ports::post_repository::{PostPage, PostRepository, PostStoreError};
use app::application::use_cases::posts::PostService;
use app::domain::entities::post::{Post, PostId};
use async_trait::async_trait;
use forge::core::Version;
use forge::http::{HeaderMap, HeaderValue, Method, Request, Response, Router, StatusCode, header};
use forge::security::Permission;

type TestResult = Result<(), Box<dyn Error>>;

const FORM: &str = "application/x-www-form-urlencoded";
/// A form body every rule accepts.
const VALID: &str = "title=Example+title&body=Example+body&published=true";
/// What the show page displays for [`VALID`].
const SHOWN: &str = "Example title";
/// Text of the error shown for [`invalid`].
const INVALID_MESSAGE: &str = "be blank";

/// A form body with one value that breaks a rule.
fn invalid() -> String {
    "title=&body=Example+body&published=true".to_owned()
}

/// Posts in memory, with the same optimistic locking as the SQL
/// repository.
#[derive(Default)]
struct InMemoryPosts {
    rows: Mutex<Vec<Post>>,
}

impl InMemoryPosts {
    fn rows(&self) -> Result<MutexGuard<'_, Vec<Post>>, PostStoreError> {
        self.rows.lock().map_err(|_| PostStoreError::Corrupt)
    }
}

#[async_trait]
impl PostRepository for InMemoryPosts {
    async fn find(&self, id: PostId) -> Result<Option<Post>, PostStoreError> {
        Ok(self
            .rows()?
            .iter()
            .find(|stored| stored.id() == id)
            .cloned())
    }

    async fn page(&self, after: Option<PostId>, limit: u16) -> Result<PostPage, PostStoreError> {
        let mut posts: Vec<Post> = self
            .rows()?
            .iter()
            .filter(|stored| after.is_none_or(|after| stored.id() > after))
            .cloned()
            .collect();
        posts.sort_by_key(Post::id);
        let next = if posts.len() > usize::from(limit) {
            posts.truncate(usize::from(limit));
            posts.last().map(Post::id)
        } else {
            None
        };
        Ok(PostPage { posts, next })
    }

    async fn insert(&self, post: &Post) -> Result<(), PostStoreError> {
        self.rows()?.push(post.clone());
        Ok(())
    }

    async fn update(&self, post: &Post) -> Result<Version, PostStoreError> {
        let next = post
            .version()
            .next()
            .map_err(|_| PostStoreError::Conflict)?;
        let mut rows = self.rows()?;
        let stored = rows
            .iter_mut()
            .find(|stored| stored.id() == post.id() && stored.version() == post.version())
            .ok_or(PostStoreError::Conflict)?;
        *stored = post.clone().with_version(next);
        Ok(next)
    }

    async fn delete(&self, id: PostId, expected: Version) -> Result<(), PostStoreError> {
        let mut rows = self.rows()?;
        let before = rows.len();
        rows.retain(|stored| !(stored.id() == id && stored.version() == expected));
        if rows.len() == before {
            Err(PostStoreError::Conflict)
        } else {
            Ok(())
        }
    }
}

/// Lets every request in; stands for the policy the application chooses.
struct AllowAll;

#[async_trait]
impl GlobalAccess for AllowAll {
    async fn authorize(&self, _: &Request, _: &Permission) -> Result<(), AccessDenied> {
        Ok(())
    }
}

/// The router of the application with only the post routes, its
/// repository and the path of the collection.
struct Harness {
    router: Router,
    collection: String,
}

impl Harness {
    fn new(access: Arc<dyn GlobalAccess>) -> Result<Self, Box<dyn Error>> {
        let repository = Arc::new(InMemoryPosts::default());
        let mut router = Router::new();
        let site = app::adapters::http::site(&mut router)?;
        app::adapters::http::posts::routes(
            &mut router,
            &site,
            PostService::new(Arc::<InMemoryPosts>::clone(&repository)),
            access,
        )?;
        let collection = "/posts".to_owned();
        Ok(Self { router, collection })
    }

    fn allowing() -> Result<Self, Box<dyn Error>> {
        Self::new(Arc::new(AllowAll))
    }

    async fn get(&self, path: &str) -> Result<Response, Box<dyn Error>> {
        Ok(self
            .router
            .dispatch(request(Method::GET, path, &[], "")?)
            .await)
    }

    /// The CSRF token the new-post page issues, as a browser keeps it.
    async fn csrf_token(&self) -> Result<String, Box<dyn Error>> {
        let page = self.get(&format!("{}/new", self.collection)).await?;
        csrf_cookie(&page).ok_or_else(|| "the form page sets the CSRF cookie".into())
    }

    /// Submits `form` like the browser: cookie plus `csrf_token` field.
    async fn submit(
        &self,
        path: &str,
        token: &str,
        form: &str,
    ) -> Result<Response, Box<dyn Error>> {
        let cookie = format!("__Host-forge_csrf={token}");
        let body = format!("{form}&csrf_token={token}");
        Ok(self
            .router
            .dispatch(request(
                Method::POST,
                path,
                &[("cookie", cookie.as_str()), ("content-type", FORM)],
                &body,
            )?)
            .await)
    }

    /// Creates a post and returns its path.
    async fn create(&self, token: &str) -> Result<String, Box<dyn Error>> {
        let created = self.submit(&self.collection, token, VALID).await?;
        assert_eq!(created.status(), StatusCode::SEE_OTHER);
        location(&created)
    }
}

fn request(
    method: Method,
    uri: &str,
    headers: &[(&'static str, &str)],
    body: &str,
) -> Result<Request, Box<dyn Error>> {
    let mut map = HeaderMap::new();
    for (name, value) in headers {
        map.append(*name, HeaderValue::from_str(value)?);
    }
    Ok(Request::new_for_test(
        method,
        uri.parse()?,
        map,
        body.to_owned().into(),
        "127.0.0.1:4000".parse()?,
        forge::core::Id::<Request>::new().into_uuid(),
    ))
}

fn body(response: &Response) -> Result<String, Box<dyn Error>> {
    Ok(String::from_utf8(response.body().to_vec())?)
}

fn location(response: &Response) -> Result<String, Box<dyn Error>> {
    let value = response
        .headers()
        .get(header::LOCATION)
        .ok_or("a redirect has a Location")?;
    Ok(value.to_str()?.to_owned())
}

/// The value of the cookie `name` that a response sets.
fn set_cookie(response: &Response, name: &str) -> Option<String> {
    let prefix = format!("{name}=");
    response
        .headers()
        .get_all(header::SET_COOKIE)
        .iter()
        .filter_map(|value| value.to_str().ok())
        .find_map(|value| value.strip_prefix(prefix.as_str()).map(str::to_owned))
        .and_then(|value| value.split(';').next().map(str::to_owned))
}

fn csrf_cookie(response: &Response) -> Option<String> {
    set_cookie(response, "__Host-forge_csrf")
}

#[tokio::test]
async fn forms_without_the_page_csrf_token_are_refused() -> TestResult {
    let harness = Harness::allowing()?;

    let forged = harness
        .router
        .dispatch(request(
            Method::POST,
            &harness.collection,
            &[("content-type", FORM)],
            VALID,
        )?)
        .await;

    assert_eq!(forged.status(), StatusCode::FORBIDDEN);
    assert!(!body(&harness.get(&harness.collection).await?)?.contains(SHOWN));
    Ok(())
}

#[tokio::test]
async fn invalid_input_is_shown_again_with_422() -> TestResult {
    let harness = Harness::allowing()?;
    let token = harness.csrf_token().await?;

    let response = harness
        .submit(&harness.collection, &token, &invalid())
        .await?;

    assert_eq!(response.status(), StatusCode::UNPROCESSABLE_ENTITY);
    let page = body(&response)?;
    assert!(page.contains(INVALID_MESSAGE), "{page}");
    assert!(page.contains("name=\"csrf_token\""), "{page}");
    Ok(())
}

#[tokio::test]
async fn create_show_edit_update_and_delete() -> TestResult {
    let harness = Harness::allowing()?;
    let token = harness.csrf_token().await?;

    let created = harness.submit(&harness.collection, &token, VALID).await?;
    assert_eq!(created.status(), StatusCode::SEE_OTHER);
    assert!(set_cookie(&created, "__Host-forge_flash").is_some());
    let member = location(&created)?;
    assert!(member.starts_with(&harness.collection), "{member}");

    let shown = harness.get(&member).await?;
    assert_eq!(shown.status(), StatusCode::OK);
    assert!(body(&shown)?.contains(SHOWN));
    let index = harness.get(&harness.collection).await?;
    assert!(body(&index)?.contains(&member));
    let edit = harness.get(&format!("{member}/edit")).await?;
    assert_eq!(edit.status(), StatusCode::OK);
    assert!(body(&edit)?.contains("name=\"version\" value=\"1\""));

    let updated = harness
        .submit(&member, &token, &format!("{VALID}&_method=patch&version=1"))
        .await?;
    assert_eq!(updated.status(), StatusCode::SEE_OTHER);
    assert_eq!(location(&updated)?, member);

    let deleted = harness
        .submit(&member, &token, "_method=delete&version=2")
        .await?;
    assert_eq!(deleted.status(), StatusCode::SEE_OTHER);
    assert_eq!(location(&deleted)?, harness.collection);
    assert_eq!(harness.get(&member).await?.status(), StatusCode::NOT_FOUND);
    Ok(())
}

#[tokio::test]
async fn stale_versions_are_conflicts() -> TestResult {
    let harness = Harness::allowing()?;
    let token = harness.csrf_token().await?;
    let member = harness.create(&token).await?;
    let first = harness
        .submit(&member, &token, &format!("{VALID}&_method=patch&version=1"))
        .await?;
    assert_eq!(first.status(), StatusCode::SEE_OTHER);

    let stale = harness
        .submit(&member, &token, &format!("{VALID}&_method=patch&version=1"))
        .await?;
    assert_eq!(stale.status(), StatusCode::CONFLICT);
    let page = body(&stale)?;
    assert!(page.contains("changed by someone else"), "{page}");
    assert!(page.contains("name=\"version\" value=\"2\""), "{page}");

    let stale_delete = harness
        .submit(&member, &token, "_method=delete&version=1")
        .await?;
    assert_eq!(stale_delete.status(), StatusCode::SEE_OTHER);
    assert_eq!(location(&stale_delete)?, member);
    assert_eq!(harness.get(&member).await?.status(), StatusCode::OK);
    Ok(())
}

#[tokio::test]
async fn unknown_and_malformed_ids_are_not_found() -> TestResult {
    let harness = Harness::allowing()?;

    for path in [
        format!("{}/{}", harness.collection, PostId::new()),
        format!("{}/not-an-id", harness.collection),
        format!("{}/{}/edit", harness.collection, PostId::new()),
    ] {
        let response = harness.get(&path).await?;
        assert_eq!(response.status(), StatusCode::NOT_FOUND, "{path}");
        assert!(body(&response)?.contains("not found"), "{path}");
    }
    Ok(())
}

#[tokio::test]
async fn the_generated_deny_all_default_refuses_every_page() -> TestResult {
    let harness = Harness::new(Arc::new(DenyAll))?;
    let id = PostId::new();
    let member = format!("{}/{id}", harness.collection);

    for path in [
        harness.collection.clone(),
        format!("{}/new", harness.collection),
        member.clone(),
        format!("{member}/edit"),
    ] {
        assert_eq!(
            harness.get(&path).await?.status(),
            StatusCode::FORBIDDEN,
            "{path}"
        );
    }

    // CSRF protection is a double-submit check, so any well-formed token in
    // both the cookie and the form passes it: the allowing router accepts
    // this one, and the 403s below therefore come from DenyAll.
    let token = "ab".repeat(32);
    let allowing = Harness::allowing()?;
    let accepted = allowing.submit(&allowing.collection, &token, VALID).await?;
    assert_eq!(accepted.status(), StatusCode::SEE_OTHER);
    let edit = format!("{VALID}&_method=patch&version=1");
    for (path, form) in [
        (harness.collection.as_str(), VALID),
        (member.as_str(), edit.as_str()),
        (member.as_str(), "_method=put&version=1"),
        (member.as_str(), "_method=delete&version=1"),
    ] {
        let refused = harness.submit(path, &token, form).await?;
        assert_eq!(refused.status(), StatusCode::FORBIDDEN, "{path} {form}");
        assert!(set_cookie(&refused, "__Host-forge_flash").is_none());
    }
    Ok(())
}
